{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "axis",
      "type": "'inline' | 'block' | 'both'",
      "description": "Logical axis or axes where native scrolling is allowed.",
      "default": "'block'"
    },
    {
      "name": "label",
      "type": "string",
      "description": "Accessible name for the viewport when it becomes keyboard scrollable.",
      "required": true
    },
    {
      "name": "role",
      "type": "'group' | 'region'",
      "description": "Semantics for the named viewport; use `region` only for areas that belong in landmark navigation.",
      "default": "'group'"
    },
    {
      "name": "overscroll",
      "type": "'allow' | 'contain'",
      "description": "Whether effective axes continue scrolling an ancestor at their edge.",
      "default": "'allow'"
    },
    {
      "name": "width",
      "type": "SizeValue",
      "description": "Width of the viewport; a number is interpreted as pixels, a string is used as-is."
    },
    {
      "name": "height",
      "type": "SizeValue",
      "description": "Height of the viewport; a number is interpreted as pixels, a string is used as-is."
    },
    {
      "name": "maxWidth",
      "type": "SizeValue",
      "description": "Maximum width of the viewport."
    },
    {
      "name": "minHeight",
      "type": "SizeValue",
      "description": "Minimum height of the viewport."
    },
    {
      "name": "stickyContainment",
      "type": "'whenScrollable' | 'always'",
      "description": "Whether fitting content passes Sticky ownership to an outer container or deliberately keeps this viewport as the CSS Sticky boundary.",
      "default": "'whenScrollable'"
    },
    {
      "name": "padding",
      "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
      "description": "Content padding on every logical edge; publishes matching inset geometry.",
      "default": "0"
    },
    {
      "name": "paddingInline",
      "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
      "description": "Logical inline-axis content padding; overrides `padding` on that axis."
    },
    {
      "name": "paddingInlineStart",
      "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
      "description": "Logical inline-start content padding; overrides broader padding values."
    },
    {
      "name": "paddingInlineEnd",
      "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
      "description": "Logical inline-end content padding; overrides broader padding values."
    },
    {
      "name": "paddingBlock",
      "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
      "description": "Logical block-axis content padding; overrides `padding` on that axis."
    },
    {
      "name": "paddingBlockStart",
      "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
      "description": "Logical block-start content padding; overrides broader padding values."
    },
    {
      "name": "paddingBlockEnd",
      "type": "0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10",
      "description": "Logical block-end content padding; overrides broader padding values."
    },
    {
      "name": "isFullBleed",
      "type": "boolean",
      "description": "Lets the viewport escape inherited container padding without changing content padding.",
      "default": "false"
    },
    {
      "name": "children",
      "type": "ReactNode",
      "description": "Content rendered inside the observed content box."
    },
    {
      "name": "xstyle",
      "type": "StyleXStyles",
      "description": "StyleX sizing and native scrollbar presentation overrides for the viewport. Must be a `stylex.create()` value, not an inline style object."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
